{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.meta_scorecard as WITH flattened_action_values AS ( SELECT AD_ID, DATE_START, SUM(CASE WHEN av.value:action_type::STRING = \'omni_purchase\' THEN av.value:value::FLOAT END) AS total_purchase FROM facebook_snitch_customad_insights, LATERAL FLATTEN(input => TRY_PARSE_JSON(ACTION_VALUES)) AS av GROUP BY AD_ID, DATE_START ), flattened_action_values_offline AS ( SELECT AD_ID, DATE_START, SUM(CASE WHEN av.value:action_type::STRING = \'offline_conversion.purchase\' THEN av.value:value::FLOAT END) AS total_purchase_offline FROM facebook_snitch_customad_insights, LATERAL FLATTEN(input => TRY_PARSE_JSON(ACTION_VALUES)) AS av GROUP BY AD_ID, DATE_START ), flattened_actions AS ( SELECT AD_ID, DATE_START, SUM(CASE WHEN ac.value:action_type::STRING = \'omni_landing_page_view\' THEN ac.value:value::FLOAT END) AS total_landing_page_views, SUM(CASE WHEN ac.value:action_type::STRING = \'omni_add_to_cart\' THEN ac.value:value::FLOAT END) AS Add_to_cart, SUM(CASE WHEN ac.value:action_type::STRING = \'omni_purchase\' THEN ac.value:value::FLOAT END) AS Total_orders FROM facebook_snitch_customad_insights, LATERAL FLATTEN(input => TRY_PARSE_JSON(ACTIONS)) AS ac GROUP BY AD_ID, DATE_START ), ad_start_date AS ( SELECT AD_ID, MIN(DATE_START) AS ad_start_date FROM facebook_snitch_customad_insights GROUP BY AD_ID ), base AS ( SELECT DISTINCT AD_ID, AD_NAME, ADSET_NAME, ADSET_ID, ACCOUNT_NAME, ACCOUNT_ID, CAMPAIGN_NAME, CAMPAIGN_ID, SPEND, impressions, DATE_START AS date FROM facebook_snitch_customad_insights ) SELECT b.AD_NAME, case when lower(ad_name) like \'%video+catalogue%\' then \'video+catalogue\' when lower(ad_name) like \'%video%\' then \'video\' when lower(ad_name) like \'%carousel%\' or lower(ad_name) like \'%carousal%\' then \'carousel\' when lower(ad_name) like \'%image%\' then \'image\' when lower(ad_name) like \'%catalogue%\' or lower(ad_name) like \'catalogad\' or lower(ad_name) like \'no cut size\' then \'catalogue\' else \'others\' end as media, case when lower(ad_name) like \'%cp%\' then \'cp\' when lower(ad_name) like \'%influencer%\' or lower(ad_name) like \'%influ%\' then \'influencer\' when lower(ad_name) like \'%buzzlab%\' then \'buzzlab\' when lower(ad_name) like \'%growster%\' then \'growster\' when lower(ad_name) like \'%inhouse%\' or lower(ad_name) like \'%in-house%\' then \'inhouse\' else \'others\' end as source_list, case when lower(adset_name) like \'%geo_wis%\' then \'Geo_WIS\' when lower(adset_name) like \'%web&instore%\' then \'web&instore\' else \'nwis\' end as type, case when lower(ad_name) like \'%offline%\' or lower(adset_name) like \'%web&instore%\' then \'offline\' when lower(ad_name) like \'%plus%\' then \'Plus\' when lower(ad_name) like \'%quick%\' then \'Quick\' when lower(ad_name) like \'%x day%\' or lower(ad_name) like \'%xday%\' then \'X Day\' when lower(ad_name) like \'%t-shirt%\' or lower(ad_name) like \'%tshirt%\' or lower(ad_name) like \'%polo%\' then \'T-Shirts\' when lower(ad_name) like \'%shirt%\' then \'Shirts\' when lower(ad_name) like \'%trouser%\' then \'Trousers\' when lower(ad_name) like \'%jean%\' then \'Jeans\' when lower(ad_name) like \'%shoe%\' then \'Shoes\' when lower(ad_name) like \'%overshirt%\' then \'Overshirt\' when lower(ad_name) like \'%cargo pant%\' or lower(ad_name) like \'%cargo%\' then \'Cargo Pants\' when lower(ad_name) like \'%collection%\' or lower(ad_name) like \'%siraj%\' or lower(ad_name) like \'%grind%\' or lower(ad_name) like \'%legacy%\' then \'Collection\' when lower(ad_name) like \'%short%\' then \'Shorts\' when lower(ad_name) like \'%bfs%\' or lower(ad_name) like \'%bday%\' or lower(ad_name) like \'%republic%\' or lower(ad_name) like \'%independence%\' or lower(ad_name) like \'%payday%\' then \'sale_event\' when lower(ad_name) like \'%new arrivals%\' or lower(ad_name) like \'%bestseller%\' or lower(ad_name) like \'%newarrivals%\' then \'NA / BS\' when lower(ad_name) like \'%perfume%\' or lower(ad_name) like \'%bag%\' or lower(ad_name) like \'%accessorie%\' or lower(ad_name) like \'%sunglass%\' then \'Longtail\' when lower(ad_name) like \'%all%\' then \'All\' when lower(ad_name) like \'%winter%\' then \'Winter wear\' when lower(ad_name) like \'%luxe%\' then \'Luxe\' when lower(ad_name) like \'%catalogue%\' or lower(ad_name) like \'%catalogad%\' or lower(ad_name) like \'%catalog%\' or lower(ad_name) like \'%no cut size%\' then \'Catalogue\' when lower(ad_name) like \'%brand%\' then \'Brand\' else \'Others\' end as category, case when lower(ad_name) like \'%catalogue%\' or lower(ad_name) like \'%shirts%\' or lower(ad_name) like \'%trousers%\' or lower(ad_name) like \'%jeans%\' or lower(ad_name) like \'%t-shirts%\' or lower(ad_name) like \'%tshirts%\' or lower(ad_name) like \'%polo%\' or lower(ad_name) like \'%all%\' or lower(ad_name) like \'%overshirt%\' or lower(ad_name) like \'%cargo pants%\' or lower(ad_name) like \'%cargo%\' or lower(ad_name) like \'%winter%\' or lower(ad_name) like \'%new arrivals%\' or lower(ad_name) like \'%bestseller%\' or lower(ad_name) like \'%quick%\' or lower(ad_name) like \'%collection%\' or lower(ad_name) like \'%x day%\' or lower(ad_name) like \'%bffs%\' or lower(ad_name) like \'%bday%\' or lower(ad_name) like \'%republic%\' or lower(ad_name) like \'%independence%\' or lower(ad_name) like \'%luxe%\' then \'shopify\' when lower(ad_name) like \'%plus%\' then \'plus\' when lower(ad_name) like \'%offline%\' or lower(adset_name) like \'%web&instore%\'then \'offline\' when lower(ad_name) like \'%shoes%\' or lower(ad_name) like \'%perfume%\' or lower(ad_name) like \'%bags%\' or lower(ad_name) like \'%accessories%\' or lower(ad_name) like \'%sunglasses%\' then \'longtail\' when lower(ad_name) like \'%brand%\' then \'brand\' else \'others\' end as bucket, b.ADSET_NAME, b.ADSET_ID, b.ACCOUNT_NAME, b.ACCOUNT_ID, b.CAMPAIGN_NAME, b.CAMPAIGN_ID, b.date, b.impressions, asd.ad_start_date, COALESCE(b.SPEND, 0) AS SPEND, COALESCE(av.total_purchase, 0) AS total_purchase, COALESCE(ac.total_landing_page_views, 0) AS total_landing_page_views, COALESCE(ac.Add_to_cart, 0) AS Add_to_cart, COALESCE(ac.Total_orders, 0) AS Total_orders, coalesce(off.total_purchase_offline,0) as total_purchase_offline FROM base b LEFT JOIN flattened_action_values av ON av.AD_ID = b.AD_ID AND av.DATE_START = b.date LEFT JOIN flattened_actions ac ON ac.AD_ID = b.AD_ID AND ac.DATE_START = b.date LEFT JOIN ad_start_date asd ON asd.AD_ID = b.AD_ID left join flattened_action_values_offline off on off.AD_ID = b.AD_ID AND off.DATE_START = b.date ORDER BY b.date DESC ;",
